onds() // DT),\n+                weight=float(d[\"weight\"]),\n+            )\n+            for d in self.demands_raw[\"demanded_windows\"]\n+        ]\n+\n+\n+def contiguous_ranges(mask: np.ndarray) -> List[Tuple[int, int]]:\n+    out: List[Tuple[int, int]] = []\n+    start = None\n+    for i, ok in enumerate(mask.tolist() + [False]):\n+        if ok and start is None:\n+            start = i\n+        elif not ok and start is not None:\n+            out.append((start, i))\n+            start = None\n+    return out\n+\n+\n+def compute_backbone_analysis() -> None:\n+    bh.initialize_eop()\n+    case = RelayCase()\n+    fc = bh.ForceModelConfig(gravity=bh.GravityConfiguration.spherical_harmonic(2, 0))\n+\n+    sat\n\n[... truncated 773 characters ...]\n\nrray(\n+            bh.position_geodetic_to_ecef(\n+                np.array([ep[\"longitude_deg\"], ep[\"latitude_deg\"], ep[\"altitude_m\"]], dtype=float),\n+                bh.AngleFormat.DEGREES,\n+            ),\n+            dtype=float,\n+        )\n+\n+    ground_access = defaultdict(dict)\n+    for ep in case.endpoints:\n+        site = endpoint_ecef[ep[\"endpoint_id\"]]\n+        min_el = math.radians(ep[\"min_elevation_deg\"])\n+        for sat in case.satellites:\n+            rel = sat_pos[sat[\"satellite_id\"]] - site\n+            horiz = np.linalg.norm(rel[:, :2] * 0.0, axis=1)\n+            mask = np.zeros(case.num_samples, dtype=bool)\n+            for i in range(case.num_samples):\n+                enz = np.array(\n+                    bh.relative_position_ecef_to_enz(\n+                        site, sat_pos[sat[\"satellite_id\"]][i], bh.EllipsoidalConversionType.GEODETIC\n+                    ),\n+                    dtype=float,\n+                )\n+                elevation = math.atan2(enz[2], math.hypot(enz[0], enz[1]))\n+                mask[i] = elevation >= min_el\n+            ground_access[ep[\"endpoint_id\"]][sat[\"satellite_id\"]] = mask\n+            print(\"ground access\", ep[\"en